for u,v,t in events:
    pair_t.setdefault(key(u,v),[]).append(t)
    adj.setdefault(u,set()).add(v); adj.setdefault(v,set()).add(u)
for k in pair_t: pair_t[k].sort()
def lb(lst,t):
    lo,hi=0,len(lst)
    while lo<hi:
        m=(lo+hi)//2
        if lst[m]<=t: lo=m+1
        else: hi=m
    return lst[lo-1] if lo>0 else None
def count(evlist,D):
